# ═══ 16.5 五常政大论（第70篇）═══
add('篇名', '16.5', '五常政大论（素问第70篇）')
add('通读', '16.5.0', '通读：本篇论五运"常政"（平气/太过/不及之政化）——木曰敷和/发生/委和，火曰升明/赫曦/伏明，土曰备化/敦阜/卑监，金曰审平/坚成/从革，水曰静顺/流衍/涸流，各述其气化、病候、物候与复气；继论地理高下寒温与"阴精所奉其人寿，阳精所降其人夭"、四方之治（西北之气散而寒之等）；末以"神机气立"（根于中者命曰神机，根于外者命曰气立）与"不知年之所加，气之盛衰，虚实之所起，不可以为工矣"作结，为运气与治则结合之专论。')
add('原文', '16.5.1.1', '黄帝问曰：太虚寥廓，五运回薄，衰盛不同，损益相从，愿闻平气何如而名？何如而纪也？')
add('原文', '16.5.1.2', '岐伯对曰：昭乎哉问也！木曰敷和，火曰升明，土曰备化，金曰审平，水曰静顺。')
add('原文', '16.5.1.3', '帝曰：其不及奈何？岐伯曰：木曰委和，火曰伏明，土曰卑监，金曰从革，水曰涸流。')
add('原文', '16.5.1.4', '帝曰：太过何谓？岐伯曰：木曰发生，火曰赫曦，土曰敦阜，金曰坚成，水曰流衍。')
add('原文', '16.5.1.5', '帝曰：三气之纪，愿闻其候。岐伯曰：悉乎哉问也！敷和之纪，木德周行，阳舒阴布，五化宣平。其气端，其性随，其用曲直，其化生荣，其类草木，其政发散，其候温和，其令风，其藏肝，肝其畏清，其主目，其谷麻，其果李，其实核，其应春，其虫毛，其畜鸡，其色苍，其养筋，其病里急支满，其味酸，其音角，其物中坚，其数八。')
add('原文', '16.5.1.6', '升明之纪，正阳而治，德施周普，五化均衡。其气高，其性速，其用燔灼，其化蕃茂，其类火，其政明曜，其候炎暑，其令热，其藏心，心其畏寒，其主舌，其谷麦，其果杏，其实络，其应夏，其虫羽，其畜马，其色赤，其养血，其病瞤瘛，其味苦，其音徵，其物脉，其数七。')
add('原文', '16.5.1.7', '备化之纪，气协天休，德流四政，五化齐修。其气平，其性顺，其用高下，其化丰满，其类土，其政安静，其候溽蒸，其令湿，其藏脾，脾其畏风，其主口，其谷稷，其果枣，其实肉，其应长夏，其虫倮，其畜牛，其色黄，其养肉，其病否，其味甘，其音宫，其物肤，其数五。')
add('原文', '16.5.1.8', '审平之纪，收而不争，杀而无犯，五化宣明。其气洁，其性刚，其用散落，其化坚敛，其类金，其政劲肃，其候清切，其令燥，其藏肺，肺其畏热，其主鼻，其谷稻，其果桃，其实壳，其应秋，其虫介，其畜鸡，其色白，其养皮毛，其病咳，其味辛，其音商，其物外坚，其数九。')
add('原文', '16.5.1.9', '静顺之纪，藏而勿害，治而善下，五化成整。其气明，其性下，其用沃衍，其化凝坚，其类水，其政流演，其候凝肃，其令寒，其藏肾，肾其畏湿，其主二阴，其谷豆，其果栗，其实濡，其应冬，其虫鳞，其畜彘，其色黑，其养骨髓，其病厥，其味咸，其音羽，其物濡，其数六。')
add('原文', '16.5.1.10', '故生而勿杀，长而勿罚，化而勿制，收而勿害，藏而勿抑，是谓平气。')
add('原文', '16.5.1.11', '委和之纪，是谓胜生，生气不政，化气乃扬，长气自平，收令乃早。凉雨时降，风云并兴，草木晚荣，苍干雕落，物秀而实，肤肉内充。其气敛，其用聚，其动緛戾拘缓，其发燥槁，其藏肝，其果枣李，其实核壳，其谷稷稻，其味酸辛，其色白苍，其畜犬鸡，其虫毛介，其主雾露凄沧，其声角商。其病摇动注恐，从金化也。少角与判商同，上角与正角同，上商与正商同。其病支废痈肿疮疡，其甘虫，邪伤肝也。上宫与正宫同。萧飋肃杀，则炎赫沸腾，眚于三，所谓复也。其主飞蠹蛆雉，乃为雷霆。')
add('原文', '16.5.1.12', '伏明之纪，是谓胜长，长气不宣，藏气反布，收气自政，化令乃衡。寒清数举，暑令乃薄，承化物生，生而不长，成实而稚，遇化已枯。其气郁，其用暴，其动彰伏变易，其发痛，其藏心，其果栗桃，其实络濡，其谷豆稻，其味苦咸，其色玄丹，其畜马彘，其虫羽鳞，其主冰雪霜寒，其声徵羽。其病昏惑悲忘，从水化也。少征与少羽同，上商与正商同。邪伤心也。凝惨栗冽，则暴雨霖霪，眚于九，所谓复也。其主骤注雷霆震惊，沉阴淫雨。')
add('原文', '16.5.1.13', '卑监之纪，是谓减化，化气不令，生政独彰，长气整，雨乃愆，收气平，风寒并兴，草木荣美，秀而不实，成而粃也。其气散，其用静定，其动疡涌分溃痈肿，其发濡滞，其藏脾，其果李栗，其实濡核，其谷豆麻，其味酸甘，其色苍黄，其畜牛犬，其虫倮毛，其主飘怒振发，其声宫角。其病留满否塞，从木化也。少宫与少角同，上宫与正宫同，上角与正角同。其病飧泄，邪伤脾也。振拉飘扬，则苍干散落，其眚四维，其主败折虎狼，清气乃用，生政乃辱。')
add('原文', '16.5.1.14', '从革之纪，是谓折收，收气乃后，生气乃扬，长化合德，火政乃宣，庶类以蕃。其气扬，其用躁切，其动铿禁瞀厥，其发咳喘，其藏肺，其果李杏，其实壳络，其谷麻麦，其味苦辛，其色白丹，其畜鸡羊，其虫介羽，其主明曜炎烁，其声商徵。其病嚏咳鼽衄，从火化也。少商与少征同，上商与正商同，上角与正角同。邪伤肺也。炎光赫烈，则冰雪霜雹，眚于七，所谓复也。其主鳞伏彘鼠，岁气早至，乃生大寒。')
add('原文', '16.5.1.15', '涸流之纪，是谓反阳，藏令不举，化气乃昌，长气宣布，蛰虫不藏，土润水泉减，草木条茂，荣秀满盛。其气滞，其用渗泄，其动坚止，其发燥槁，其藏肾，其果枣杏，其实濡肉，其谷黍稷，其味甘咸，其色黅玄，其畜彘牛，其虫鳞倮，其主埃郁昏翳，其声羽宫。其病痿厥坚下，从土化也。少羽与少宫同，上宫与正宫同。其病癃闭，邪伤肾也。埃昏骤雨，则振拉摧拔，眚于一，所谓复也。其主毛显狐貉，变化不藏。')
add('原文', '16.5.1.16', '故乘危而行，不速而至，暴虐无德，灾反及之，微者复微，甚者复甚，气之常也。')
add('原文', '16.5.1.17', '发生之纪，是谓启敕，土疏泄，苍气达，阳和布化，阴气乃随，生气淳化，万物以荣。其化生，其气美，其政散，其令条舒，其动掉眩巅疾，其德鸣靡启坼，其变振拉摧拔，其灾散于四维。其谷麻稻，其畜鸡犬，其果李桃，其色青黄白，其味酸甘辛，其象春，其经足厥阴少阳，其藏肝脾，其虫毛介，其物中坚外坚，其病怒。太角与上商同，上征则其气逆，其病吐利。不务其德则收气复，秋气劲切，甚则肃杀，清气大至，草木凋零，邪乃伤肝。')
add('原文', '16.5.1.18', '赫曦之纪，是谓蕃茂，阴气内化，阳气外荣，炎暑施化，物得以昌。其化长，其气高，其政动，其令鸣显，其动炎灼妄扰，其德暄暑郁蒸，其变炎烈沸腾，其灾燔焫。其谷麦豆，其畜羊彘，其果杏栗，其色赤白玄，其味苦辛咸，其象夏，其经手少阴太阳，手厥阴少阳，其藏心肺，其虫羽鳞，其物脉濡，其病笑疟疮疡血流狂妄目赤。太征与上商同，上征则其气逆，其病吐利。不务其德则收气复，秋气劲切，甚则肃杀，清气大至，草木凋零，邪乃伤心。')
add('原文', '16.5.1.19', '敦阜之纪，是谓广化，厚德清静，顺长以盈，至阴内实，物化充成，烟埃朦郁，见于厚土。大雨时行，湿气乃用，燥政乃辟。其化圆，其气丰，其政静，其令周备，其动濡积并稸，其德柔润重淖，其变震惊飘骤，其灾霖溃。其谷稷麻，其畜牛犬，其果枣李，其色黅玄苍，其味甘咸酸，其象长夏，其经足太阴阳明，其藏脾肾，其虫倮毛，其物肌核，其病腹满四支不举。大风迅至，邪伤脾也。')
add('原文', '16.5.1.20', '坚成之纪，是谓收引，天气洁，地气明，阳气随，阴治化，燥行其政，物以司成，收气繁布，化洽不终。其化成，其气削，其政肃，其令锐切，其动暴折疡疰，其德雾露萧飋，其变肃杀凋零，其灾苍陨。其谷稻黍，其畜鸡马，其果桃杏，其色白青丹，其味辛酸苦，其象秋，其经手太阴阳明，其藏肺肝，其虫介羽，其物壳络，其病喘喝，胸凭仰息。上征与正商同，其生齐，其病咳。政暴变，则名木不荣，柔脆焦首，长气斯救，大火流，炎烁且至，蔓将槁，邪伤肺也。')
add('原文', '16.5.1.21', '流衍之纪，是谓封藏，寒司物化，天地严凝，藏政以布，长令不扬。其化凛，其气坚，其政谧，其令流注，其动漂泄沃涌，其德凝惨寒雰，其变冰雪霜雹，其灾水泉，物变鳞见。其谷豆稷，其畜彘牛，其果栗枣，其色黑丹黅，其味咸苦甘，其象冬，其经足少阴太阳，其藏肾心，其虫鳞倮，其物濡满，其病胀。上羽而长气不化也。政过则化气大举，而埃昏气交，大雨时降，邪伤肾也。')
add('原文', '16.5.1.22', '故曰：不但其德，则所胜来复；政恒其理，则所胜同化。此之谓也。')
add('原文', '16.5.1.23', '帝曰：天不足西北，左寒而右凉；地不满东南，右热而左温，其故何也？岐伯曰：阴阳之气，高下之理，太少之异也。东南方，阳也，阳者其精降于下，故右热而左温。西北方，阴也，阴者其精奉于上，故左寒而右凉。是以地有高下，气有温凉，高者气寒，下者气热。故适寒凉者胀，之温热者疮，下之则胀已，汗之则疮已，此腠理开闭之常，太少之异耳。')
add('原文', '16.5.1.24', '帝曰：其于寿夭何如？岐伯曰：阴精所奉其人寿，阳精所降其人夭。')
add('原文', '16.5.1.25', '帝曰：善。其病也，治之奈何？岐伯曰：西北之气散而寒之，东南之气收而温之，所谓同病异治也。故曰：气寒气凉，治以寒凉，行水渍之；气温气热，治以温热，强其内守。必同其气，可使平也，假者反之。')
add('原文', '16.5.1.26', '帝曰：善。一州之气，生化寿夭不同，其故何也？岐伯曰：高下之理，地势使然也。崇高则阴气治之，污下则阳气治之，阳胜者先天，阴胜者后天，此地理之常，生化之道也。')
add('原文', '16.5.1.27', '帝曰：其有寿夭乎？岐伯曰：高者其气寿，下者其气夭，地之小大异也，小者小异，大者大异。故治病者，必明天道地理，阴阳更胜，气之先后，人之寿夭，生化之期，乃可以知人之形气矣。')
add('原文', '16.5.1.28', '帝曰：善。其岁有不病，而藏气不应不用者何也？岐伯曰：天气制之，气有所从也。')
add('原文', '16.5.1.29', '帝曰：愿卒闻之。岐伯曰：少阳司天，火气下临，肺气上从，白起金用，草木眚，火见燔焫，革金且耗，大暑以行，咳嚏鼽衄鼻窒，曰疡，寒热胕肿。风行于地，尘沙飞扬，心痛胃脘痛，厥逆鬲不通，其主暴速。')
add('原文', '16.5.1.30', '阳明司天，燥气下临，肝气上从，苍起木用而立，土乃眚，凄沧数至，木伐草萎，胁痛目赤，掉振鼓栗，筋痿不能久立。暴热至，土乃暑，阳气郁发，小便变，寒热如疟，甚则心痛，火行于稿，流水不冰，蛰虫乃见。')
add('原文', '16.5.1.31', '太阳司天，寒气下临，心气上从，而火且明，丹起金乃眚，寒清时举，胜则水冰，火气高明，心热烦，嗌干善渴，鼽嚏，喜悲数欠，热气妄行，寒乃复，霜不时降，善忘，甚则心痛。土乃润，水丰衍，寒客至，沉阴化，湿气变物，水饮内稸，中满不食，皮𤸷肉苛，筋脉不利，甚则胕肿身后痈。')
add('原文', '16.5.1.32', '厥阴司天，风气下临，脾气上从，而土且隆，黄起水乃眚，土用革，体重肌肉萎，食减口爽，风行太虚，云物摇动，目转耳鸣。火纵其暴，地乃暑，大热消烁，赤沃下，蛰虫数见，流水不冰，其发机速。')
add('原文', '16.5.1.33', '少阴司天，热气下临，肺气上从，白起金用，草木眚，喘呕寒热，嚏鼽衄鼻窒，大暑流行，甚则疮疡燔灼，金烁石流。地乃燥清，凄沧数至，胁痛善太息，肃杀行，草木变。')
add('原文', '16.5.1.34', '太阴司天，湿气下临，肾气上从，黑起水变，埃冒云雨，胸中不利，阴痿气大衰而不起不用，当其时反腰脽痛，动转不便也，厥逆。地乃藏阴，大寒且至，蛰虫早附，心下否痛，地裂冰坚，少腹痛，时害于食，乘金则止水增，味乃咸，行水减也。')
add('原文', '16.5.1.35', '帝曰：岁有胎孕不育，治之不全，何气使然？岐伯曰：六气五类，有相胜制也。同者盛之，异者衰之。此天地之道，生化之常也。')
add('原文', '16.5.1.36', '故厥阴司天，毛虫静，羽虫育，介虫不成；在泉，毛虫育，倮虫耗，羽虫不育。少阴司天，羽虫静，介虫育，毛虫不成；在泉，羽虫育，介虫耗不育。太阴司天，倮虫静，鳞虫育，羽虫不成；在泉，倮虫育，鳞虫不成。少阳司天，羽虫静，毛虫育，倮虫不成；在泉，羽虫育，介虫耗，毛虫不育。阳明司天，介虫静，羽虫育，介虫不成；在泉，介虫育，毛虫耗，羽虫不成。太阳司天，鳞虫静，倮虫育；在泉，鳞虫耗，倮虫不育。')
add('原文', '16.5.1.37', '诸乘所不成之运，则甚也。故气主有所制，岁立有所生。地气制己胜，天气制胜己。天制色，地制形，五类衰盛，各随其气之所宜也。故有胎孕不育，治之不全，此气之常也，所谓中根也。根于外者亦五，故生化之别，有五气五味五色五类五宜也。')
add('原文', '16.5.1.38', '帝曰：何谓也？岐伯曰：根于中者，命曰神机，神去则机息；根于外者，命曰气立，气止则化绝。故各有制，各有胜，各有生，各有成。故曰：不知年之所加，气之盛衰，虚实之所起，不可以为工矣。')
add('注释', '16.5.1.39', '本篇注释：①"木曰敷和…水曰静顺"等平气/不及/太过之三气纪名——运气政化之名目，义理可解（通行）。②"其数八/七/五/九/六"（五行成数生数：天一生水地六成之等）——河洛数理之引入，其来源与推演古今多歧，**悬疑存疑**。③"阴精所奉其人寿，阳精所降其人夭"与"西北之气散而寒之，东南之气收而温之"——地理与寿夭、治法之关系（通行）。④"根于中者，命曰神机，神去则机息；根于外者，命曰气立，气止则化绝"——神机气立之生命观，为内经生命理论之名论（通行）。⑤"六气五类，有相胜制也…同者盛之，异者衰之"——五虫（毛羽倮介鳞）与六气之胜制，其物候推演历代或有出入，**悬疑存疑**。')

# ═══ 16.6 六元正纪大论（第71篇）═══
add('篇名', '16.6', '六元正纪大论（素问第71篇）')
add('通读', '16.6.0', '通读：本篇为运气正纪之总汇——"六化六变，胜复淫治"，详述六十年甲子之运气正纪（六气司天在泉、主气客气、运气相合、五运太过不及），论"六气之用，各归不胜而为化"与"折其郁气，资其化源"之治则，并提出"木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之"五郁治则与"有故无殒，亦无殒也"之孕妇用药权衡，为运气历谱之最详者。')
add('原文', '16.6.1.1', '黄帝问曰：六化六变，胜复淫治，甘苦辛咸酸淡先后，余知之矣。夫五运之化，或从五气，或逆天气，或从天气而逆地气，或从地气而逆天气，或相得，或不相得，余未能明其事。欲通天之纪，从地之理，和其运，调其化，使上下合德，无相夺伦，天地升降，不失其宜，五运宣行，勿乖其政，调之正味从逆奈何？')
add('原文', '16.6.1.2', '岐伯稽首再拜对曰：昭乎哉问也！此天地之纲纪，变化之渊源，非圣帝孰能穷其至理欤！臣虽不敏，请陈其道，令终不灭，久而不易。')
add('原文', '16.6.1.3', '帝曰：愿夫子推而次之，从其类序，分其部主，别其宗司，昭其气数，明其正化，可得闻乎？岐伯曰：先立其年，以明其气，金木水火土运行之数，寒暑燥湿风火临御之化，则天道可见，民气可调，阴阳卷舒，近而无惑，数之可数者，请遂言之。')
add('原文', '16.6.1.4', '帝曰：太阳之政奈何？岐伯曰：辰戌之纪也。')
add('原文', '16.6.1.5', '太阳太角太阴壬辰壬戌，其运风，其化鸣紊启坼，其变振拉摧拔，其病眩掉目瞑。太角初正少征太宫少商太羽终。')
add('原文', '16.6.1.6', '太阳太征太阴戊辰戊戌同正征，其运热，其化暄暑郁燠，其变炎烈沸腾，其病热郁。太征少宫太商少羽终少角。')
add('原文', '16.6.1.7', '太阳太宫太阴甲辰岁会甲戌岁会，其运阴埃，其化柔润重泽，其变震惊飘骤，其病湿下重。太宫少商太羽终太角少征。')
add('原文', '16.6.1.8', '太阳太商太阴庚辰庚戌，其运凉，其化雾露萧飋，其变肃杀凋零，其病燥背瞀胸满。太商少羽终少角太征少宫。')
add('原文', '16.6.1.9', '太阳太羽太阴丙辰天符丙戌天符，其运寒，其化凝惨栗冽，其变冰雪霜雹，其病大寒留于溪谷。太羽终太角少征太宫少商。')
add('原文', '16.6.1.10', '凡此太阳司天之政，气化运行先天，天气肃，地气静，寒临太虚，阳气不令，水土合德，上应辰星镇星。其谷玄黅，其政肃，其令徐。寒政大举，泽无阳焰，则火发待时。少阳中治，时雨乃涯。止极雨散，还于太阴，云朝北极，湿化乃布，泽流万物。寒敷于上，雷动于下，寒湿之气，持于气交。民病寒湿，发肌肉萎，足痿不收，濡泻血溢。')
add('原文', '16.6.1.11', '初之气，地气迁，气乃大温，草乃早荣，民乃厉，温病乃作，身热头痛呕吐，肌腠疮疡。二之气，大凉反至，民乃惨，草乃遇寒，火气遂抑，民病气郁中满，寒乃始。三之气，天政布，寒气行，雨乃降，民病寒，反热中，痈疽注下，心热瞀闷，不治者死。四之气，风湿交争，风化为雨，乃长乃化乃成，民病大热少气，肌肉萎足痿，注下赤白。五之气，阳复化，草乃长乃化乃成，民乃舒。终之气，地气正，湿令行，阴凝太虚，埃昏郊野，民乃惨凄，寒风以至，反者孕乃死。')
add('原文', '16.6.1.12', '故岁宜苦以燥之温之，必折其郁气，先资其化源，抑其运气，扶其不胜，无使暴过而生其疾。食岁谷以全其真，避虚邪以安其正。适气同异，多少制之，同寒湿者燥热化，异寒湿者燥湿化。故同者多之，异者少之。用寒远寒，用凉远凉，用温远温，用热远热，食宜同法。有假者反常，反是者病，所谓时也。')
add('原文', '16.6.1.13', '帝曰：善。阳明之政奈何？岐伯曰：卯酉之纪也。')
add('原文', '16.6.1.14', '阳明少角少阴，清热胜复同，同正商。丁卯岁会丁酉，其运风，其化鸣紊启坼，其变振拉摧拔，其病下血。少角初正太征少宫太商少羽终。')
add('原文', '16.6.1.15', '阳明少征少阴，寒雨胜复同，同正商。癸卯癸酉，其运热，其化暄暑郁燠，其变炎烈沸腾，其病热。太征少宫太商少羽终少角。')
add('原文', '16.6.1.16', '阳明少宫少阴，风凉胜复同。己卯己酉，其运雨风凉，其化柔润重泽，其变震惊飘骤，其病湿。太宫少商太羽终太角少征。')
add('原文', '16.6.1.17', '阳明少商少阴，热寒胜复同，同正商。乙卯天符乙酉岁会，太乙天符，其运凉，其化雾露萧飋，其变肃杀凋零，其病燥。太商少羽终少角太征少宫。')
add('原文', '16.6.1.18', '阳明少羽少阴，雨风胜复同，同少宫。辛卯辛酉，其运寒，其化凝惨栗冽，其变冰雪霜雹，其病寒。太羽终太角少征太宫少商。')
add('原文', '16.6.1.19', '凡此阳明司天之政，气化运行后天，天气急，地气明，阳专其令，炎暑大行，物燥以坚，淳风乃治，风燥横运，流于气交，多阳少阴，云趋雨府，湿化乃敷。燥极而泽，其谷白丹，间谷命太者。其耗白甲品羽，金火合德，上应太白荧惑。其政切，其令暴。蛰虫乃见，流水不冰。民病咳嗌塞，寒热发暴，振栗癃闭，清先而劲，毛虫乃死，热后而暴，介虫乃殃。其发躁，胜复之作，扰而大乱，清气大来，燥之而胜，风木受邪，肝病生焉。')
add('原文', '16.6.1.20', '初之气，地气迁，阴始凝，气始肃，水乃冰，寒雨化。其病中热胀，面目浮肿，善眠，鼽衄嚏欠呕，小便黄赤，甚则淋。二之气，阳乃布，民乃舒，物乃生荣，厉大至，民善暴死。三之气，天政布，凉乃行，燥热交合，燥极而泽，民病寒热。四之气，寒雨降，病暴仆，振栗谵妄，少气嗌干引饮，及为心痛痈肿疮疡疟寒之疾，骨痿血便。五之气，春令反行，草乃荣，民气和。终之气，阳气布，候反温，蛰虫来见，流水不冰，民乃康平，其病温。')
add('原文', '16.6.1.21', '故食岁谷以安其气，食间谷以去其邪，岁宜以咸以苦以辛，汗之清之散之，安其运气，无使受邪，折其郁气，资其化源。以寒热轻重少多其制，同热者多天化，同清者多地化。用凉远凉，用热远热，用寒远寒，用温远温，食宜同法。有假者反之，此其道也。反是者，乱天地之经，扰阴阳之纪也。')
add('原文', '16.6.1.22', '帝曰：善。少阳之政奈何？岐伯曰：寅申之纪也。')
add('原文', '16.6.1.23', '少阳太角厥阴壬寅壬申，其运风鼓，其化鸣紊启坼，其变振拉摧拔，其病掉眩支胁惊骇。太角初正少征太宫少商太羽终。')
add('原文', '16.6.1.24', '少阳太征厥阴戊寅天符戊申天符，其运暑，其化暄嚣郁燠，其变炎烈沸腾，其病上热郁血溢血泄心痛。太征少宫太商少羽终少角。')
add('原文', '16.6.1.25', '少阳太宫厥阴甲寅甲申，其运阴雨，其化柔润重泽，其变震惊飘骤，其病体重胕肿痞饮。太宫少商太羽终太角少征。')
add('原文', '16.6.1.26', '少阳太商厥阴庚寅庚申同正商，其运凉，其化雾露清切，其变肃杀凋零，其病肩背胸中痛。太商少羽终少角太征少宫。')
add('原文', '16.6.1.27', '少阳太羽厥阴丙寅丙申，其运寒肃，其化凝惨栗冽，其变冰雪霜雹，其病寒浮肿。太羽终太角少征太宫少商。')
add('原文', '16.6.1.28', '凡此少阳司天之政，气化运行先天，天气正，地气扰，风乃暴举，木偃沙飞，炎火乃流，阴行阳化，雨乃时应。火木同德，上应荧惑岁星。其谷丹苍，其政严，其令扰。故风热参布，云物沸腾，太阴横流，寒乃时至，凉雨并起。民病寒中，外发疮疡，内为泄满。故圣人遇之，和而不争。往复之作，民病寒热疟泄，聋瞑呕吐，上怫肿色变。')
add('原文', '16.6.1.29', '初之气，地气迁，风胜乃摇，寒乃去，候乃大温，草木早荣，寒来不杀，温病乃起，其病气怫于上，血溢目赤，咳逆头痛，血崩胁满，肤腠中疮。二之气，火反郁，白埃四起，云趋雨府，风不胜湿，雨乃零，民乃康，其病热郁于上，咳逆呕吐，疮发于中，胸嗌不利，头痛身热，昏愦脓疮。三之气，天政布，炎暑至，少阳临上，雨乃涯，民病热中，聋瞑血溢，脓疮咳呕，鼽衄渴嚏欠，喉痹目赤，善暴死。四之气，凉乃至，炎暑间化，白露降，民气和平，其病满身重。五之气，阳乃去，寒乃来，雨乃降，气门乃闭，刚木早雕，民避寒邪，君子周密。终之气，地气正，风乃至，万物反生，霿雾以行，其病关闭不禁，心痛，阳气不藏而咳。')
add('原文', '16.6.1.30', '抑其运气，赞所不胜，必折其郁气，先取其化源，暴过不生，苛疾不起。故岁宜咸辛宜酸，渗之泄之，渍之发之，观气寒温以调其过，同风热者多寒化，异风热者少寒化。用热远热，用温远温，用寒远寒，用凉远凉，食宜同法。此其道也。有假者反之，反是者病之阶也。')
add('原文', '16.6.1.31', '帝曰：善。太阴之政奈何？岐伯曰：丑未之纪也。')
add('原文', '16.6.1.32', '太阴少角太阳，清热胜复同，同正宫。丁丑丁未，其运风，其化鸣紊启坼，其变振拉摧拔，其病体重飧泄，脐下小腹坚。少角初正太征少宫太商少羽终。')
add('原文', '16.6.1.33', '太阴少征太阳，寒雨胜复同。癸丑癸未，其运热，其化暄暑郁燠，其变炎烈沸腾，其病血溢。太征少宫太商少羽终少角。')
add('原文', '16.6.1.34', '太阴少宫太阳，风清胜复同，同正宫。己丑太一天符己未太一天符，其运雨风清，其化柔润重泽，其变震惊飘骤，其病体重胕肿痞饮。太宫少商太羽终太角少征。')
add('原文', '16.6.1.35', '太阴少商太阳，热寒胜复同。乙丑乙未，其运凉，其化雾露萧飋，其变肃杀凋零，其病疮疡胕肿。太商少羽终少角太征少宫。')
add('原文', '16.6.1.36', '太阴少羽太阳，雨风胜复同，同正宫。辛丑辛未，其运寒，其化凝惨栗冽，其变冰雪霜雹，其病寒。太羽终太角少征太宫少商。')
add('原文', '16.6.1.37', '凡此太阴司天之政，气化运行后天，阴专其政，阳气退辟，大风时起，天气下降，地气上腾，原野昏霿，白埃四起，云奔南极，寒雨数至，物成于差夏。民病寒湿，腹满身䐜愤胕肿，痞逆寒厥拘急。湿寒合德，黄黑埃昏，流行气交，上应镇星辰星。其政肃，其令寂，其谷黅玄。故阴凝于上，寒积于下，寒水胜火，则为冰雹，阳光不治，杀气乃行。')
add('原文', '16.6.1.38', '初之气，地气迁，寒乃去，春气正，风乃来，生布万物以荣，民气条舒，风湿相薄，雨乃后。民病血溢，筋络拘强，关节不利，身重筋痿。二之气，大火正，物承化，民乃和，其病温厉大行，远近咸若，湿蒸相薄，雨乃时降。三之气，天政布，湿气降，地气腾，雨乃时降，寒乃随之，感于寒湿，则民病身重胕肿，胸腹满。四之气，畏火临，溽蒸化，地气腾，天气否隔，寒风晓暮，蒸热相薄，草木凝烟，湿化不流，则白露阴布，以成秋令，民病腠理热，血暴溢疟，心腹满热，胪胀，甚则胕肿。五之气，惨令已行，寒露下，霜乃早降，草木黄落，寒气及体，君子周密，民病皮腠。终之气，寒大举，湿大化，霜乃积，阴乃凝，水坚冰，阳光不治，感于寒，则病人关节禁固，腰脽痛，寒湿持于气交而为疾也。')
add('原文', '16.6.1.39', '必折其郁气，而取化源，益其岁气，无使邪胜。食岁谷以全其真，食间谷以保其精。故岁宜以苦燥之温之，甚者发之泄之，不发不泄，则湿气外溢，肉溃皮坼而水血交流。必赞其阳火，令御甚寒。从气异同，少多其判也。同寒者以热化，同湿者以燥化，异者少之，同者多之。用凉远凉，用寒远寒，用温远温，用热远热，食宜同法。假者反之，此其道也。反是者病也。')
add('原文', '16.6.1.40', '帝曰：善。少阴之政奈何？岐伯曰：子午之纪也。')
add('原文', '16.6.1.41', '少阴太角阳明壬子壬午，其运风鼓，其化鸣紊启坼，其变振拉摧拔，其病支满。太角初正少征太宫少商太羽终。')
add('原文', '16.6.1.42', '少阴太征阳明戊子天符戊午太一天符，其运炎暑，其化暄曜郁燠，其变炎烈沸腾，其病上热血溢。太征少宫太商少羽终少角。')
add('原文', '16.6.1.43', '少阴太宫阳明甲子甲午，其运阴雨，其化柔润时雨，其变震惊飘骤，其病中满身重。太宫少商太羽终太角少征。')
add('原文', '16.6.1.44', '少阴太商阳明庚子庚午同正商，其运凉劲，其化雾露萧飋，其变肃杀凋零，其病下清。太商少羽终少角太征少宫。')
add('原文', '16.6.1.45', '少阴太羽阳明丙子岁会丙午，其运寒，其化凝惨栗冽，其变冰雪霜雹，其病寒下。太羽终太角少征太宫少商。')
add('原文', '16.6.1.46', '凡此少阴司天之政，气化运行先天，地气肃，天气明，寒交暑，热加燥，云驰雨府，湿化乃行，时雨乃降，金火合德，上应荧惑太白。其政明，其令切，其谷丹白。水火寒热持于气交而为病始也。热病生于上，清病生于下，寒热凌犯而争于中，民病咳喘，血溢血泄，鼽嚏目赤，眦疡，寒厥入胃，心痛腰痛，腹大嗌干肿上。')
add('原文', '16.6.1.47', '初之气，地气迁，暑将去，寒乃始，蛰复藏，水乃冰，霜复降，风乃至，阳气郁，民反周密，关节禁固，腰脽痛，炎暑将起，中外疮疡。二之气，阳气布，风乃行，春气以正，万物应荣，寒气时至，民乃和，其病淋，目瞑目赤，气郁于上而热。三之气，天政布，大火行，庶类蕃鲜，寒气时至，民病气厥心痛，寒热更作，咳喘目赤。四之气，溽暑至，大雨时行，寒热互至，民病寒热，嗌干黄瘅，鼽衄饮发。五之气，畏火临，暑反至，阳乃化，万物乃生乃长乃荣，民乃康，其病温。终之气，燥令行，余火内格，肿于上，咳喘，甚则血溢，寒气数举，则霿雾翳，病生皮腠，内舍于胁，下连少腹而作寒中，地将易也。')
add('原文', '16.6.1.48', '必抑其运气，资其岁胜，折其郁发，先取化源，无使暴过而生其病也。食岁谷以全真气，食间谷以辟虚邪。岁宜咸以耎之，而调其上，甚则以苦泄之，以酸收之，而安其下，甚则以苦泄之。适气同异而多少之，同天气者以寒清化，同地气者以温热化。用热远热，用凉远凉，用温远温，用寒远寒，食宜同法。有假则反，此其道也。反是者病作矣。')
add('原文', '16.6.1.49', '帝曰：善。厥阴之政奈何？岐伯曰：巳亥之纪也。')
add('原文', '16.6.1.50', '厥阴少角少阳，清热胜复同，同正角。丁巳天符丁亥天符，其运风，其化鸣紊启坼，其变振拉摧拔，其病掉眩支胁惊骇。少角初正太征少宫太商少羽终。')
add('原文', '16.6.1.51', '厥阴少征少阳，寒雨胜复同。癸巳癸亥，其运热，其化暄暑郁燠，其变炎烈沸腾，其病热。太征少宫太商少羽终少角。')
add('原文', '16.6.1.52', '厥阴少宫少阳，风清胜复同，同正角。己巳己亥，其运雨风清，其化柔润重泽，其变震惊飘骤，其病体重胕肿痞饮。太宫少商太羽终太角少征。')
add('原文', '16.6.1.53', '厥阴少商少阳，热寒胜复同。乙巳乙亥，其运凉，其化雾露萧飋，其变肃杀凋零，其病疮疡胕肿。太商少羽终少角太征少宫。')
add('原文', '16.6.1.54', '厥阴少羽少阳，雨风胜复同。辛巳辛亥，其运寒，其化凝惨栗冽，其变冰雪霜雹，其病寒。太羽终太角少征太宫少商。')
add('原文', '16.6.1.55', '凡此厥阴司天之政，气化运行后天，诸同正岁，气化运行同天。天气扰，地气正，风生高远，炎热从之，云趋雨府，湿化乃行，风火同德，上应岁星荧惑。其政挠，其令速，其谷苍丹。间谷言太者，其耗文角品羽。风燥火热，胜复更作，蛰虫来见，流水不冰，热病行于下，风病行于上，风燥胜复形于中。')
add('原文', '16.6.1.56', '初之气，寒始肃，杀气方至，民病寒于右之下。二之气，寒不去，华雪水冰，杀气施化，霜乃降，名草上焦，寒雨数至，阳复化，民病热于中。三之气，天政布，风乃时举，民病泣出耳鸣掉眩。四之气，溽暑湿热相薄，争于左之上，民病黄瘅而为胕肿。五之气，燥湿更胜，沉阴乃布，寒气及体，风雨乃行。终之气，畏火司令，阳乃大化，蛰虫出见，流水不冰，地气大发，草乃生，人乃舒，其病温厉。')
add('原文', '16.6.1.57', '必折其郁气，资其化源，赞其运气，无使邪胜。岁宜以辛调上，以咸调下，畏火之气，无妄犯之。用温远温，用热远热，用凉远凉，用寒远寒，食宜同法。有假反常，此之道也。反是者病。')
add('原文', '16.6.1.58', '帝曰：善。夫子言可谓悉矣，然何以明其应乎？岐伯曰：昭乎哉问也！夫六气者，行有次，止有位，故常以正月朔日平旦视之，睹其位而知其所在矣。运有余，其至先；运不及，其至后。此天之道，气之常也。运非有余非不足，是谓正岁，其至当其时也。')
add('原文', '16.6.1.59', '帝曰：胜复之气，其常在也，灾眚时至，候也奈何？岐伯曰：非气化者，是谓灾也。')
add('原文', '16.6.1.60', '帝曰：天地之数，终始奈何？岐伯曰：悉乎哉问也！是明道也。数之始，起于上而终于下，岁半之前，天气主之；岁半之后，地气主之；上下交互，气交主之，岁纪毕矣。故曰：位明气月可知乎，所谓气也。')
add('原文', '16.6.1.61', '帝曰：余司其事，则而行之，不合其数何也？岐伯曰：气用有多少，化洽有盛衰，衰盛多少，同此其道也。')
add('原文', '16.6.1.62', '帝曰：愿闻同化何如？岐伯曰：风温春化同，热曛昏火夏化同，胜与复同，燥清烟露秋化同，云雨昏暝埃长夏化同，寒气霜雪冰冬化同。此天地五运六气之化，更用盛衰之常也。')
add('原文', '16.6.1.63', '帝曰：五运行同天化者，命曰天符，余知之矣。愿闻同地化者何谓也？岐伯曰：太过而同天化者三，不及而同天化者亦三，太过而同地化者三，不及而同地化者亦三。此凡二十四岁也。')
add('原文', '16.6.1.64', '帝曰：愿闻所谓岁会者何也？岐伯曰：所谓岁会者，岁半之前，天气主之；岁半之后，地气主之；上下交互，气交主之。岁纪毕矣。故曰：位明气月可知乎，所谓气也。')
add('原文', '16.6.1.65', '帝曰：其岁会之数奈何？岐伯曰：木运临卯，火运临午，土运临四季，金运临酉，水运临子，所谓岁会，气之平也。帝曰：非位何如？岐伯曰：岁不与会也。')
add('原文', '16.6.1.66', '帝曰：愿闻其用也。岐伯曰：夫六气之用，各归不胜而为化。故太阴雨化，施于太阳；太阳寒化，施于少阴；少阴热化，施于阳明；阳明燥化，施于厥阴；厥阴风化，施于太阴。各命其所在以征之也。')
add('原文', '16.6.1.67', '帝曰：自得其位何如？岐伯曰：自得其位，常化也。')
add('原文', '16.6.1.68', '帝曰：愿闻所在也。岐伯曰：命其位而方月可知也。')
add('原文', '16.6.1.69', '帝曰：六位之气盈虚何如？岐伯曰：太少异也。太者之至徐而常，少者暴而亡。')
add('原文', '16.6.1.70', '帝曰：天地之气盈虚何如？岐伯曰：天气不足，地气随之；地气不足，天气从之。运居其中而常先也。恶所不胜，归所同和，随运归从而生其病也。故上胜则天气降而下，下胜则地气迁而上，多少而差其分。微者小差，甚者大差，甚则位易气交，易则大变生而病作矣。')
add('原文', '16.6.1.71', '帝曰：善。论言热无犯热，寒无犯寒，余欲不远寒，不远热奈何？岐伯曰：悉乎哉问也！发表不远热，攻里不远寒。帝曰：不发不攻，而犯寒犯热何如？岐伯曰：寒热内贼，其病益甚。帝曰：愿闻无病者何如？岐伯曰：无者生之，有者甚之。帝曰：生者何如？岐伯曰：不远热则热至，不远寒则寒至。寒至则坚痞腹满，痛急下利之病生矣。热至则身热，吐下霍乱，痈疽疮疡，瞀郁注下，瞤瘛肿胀，呕鼽衄头痛，骨节变，肉痛，血溢血泄，淋閟之病生矣。')
add('原文', '16.6.1.72', '帝曰：治之奈何？岐伯曰：时必顺之，犯者治以胜也。')
add('原文', '16.6.1.73', '帝曰：妇人重身，毒之何如？岐伯曰：有故无殒，亦无殒也。帝曰：愿闻其故何谓也？岐伯曰：大积大聚，其可犯也，衰其大半而止，过者死。')
add('原文', '16.6.1.74', '帝曰：善。郁之甚者，治之奈何？岐伯曰：木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之。然调其气，过者折之，以其畏也，所谓泻之。')
add('原文', '16.6.1.75', '帝曰：假者何如？岐伯曰：有假其气，则无禁也。所谓主气不足，客气胜也。')
add('原文', '16.6.1.76', '帝曰：至哉圣人之道！天地大化运行之节，临御之纪，阴阳之政，寒暑之令，非夫子孰能通之！请藏之灵兰之室，署曰《六元正纪》。非斋戒不敢示，慎传也。')
add('注释', '16.6.1.77', '本篇注释：①"太阳之政…辰戌之纪也"等六十甲子运气正纪——六十年运气历谱（司天在泉、主客之气、五运太过不及、六气步位），为运气推演之最详者；其中"太角初正少征太宫少商太羽终"等五音建运之步位（角征宫商羽应木火土金水）——历算繁复，各家推演或有出入，**悬疑存疑**。②"折其郁气，资其化源"——治郁之大法（通行）。③"木郁达之，火郁发之，土郁夺之，金郁泄之，水郁折之"——五郁治则之经典（通行），为后世治郁大法之渊源。④"有故无殒，亦无殒也"——孕妇攻邪之权衡（有病则病受之）（通行）。⑤"发表不远热，攻里不远寒"与"用寒远寒，用凉远凉，用温远温，用热远热"——用药因时制宜（通行；"远"训"避"）。')

